const api = `${__API_BASE_URL__.replace(/\/$/, '')}/api/v1/`;
let accessToken = '';
const sessionKey='giri-fruits-session';
const pageKey='giri-fruits-page';
function getSaved(key:string){try{return sessionStorage.getItem(key)||''}catch{return ''}}
function setSaved(key:string,value:string){try{if(value)sessionStorage.setItem(key,value);else sessionStorage.removeItem(key)}catch{/* Storage can be unavailable in private browsing. */}}
const nativeFetch = window.fetch.bind(window);
let activeOperations=0;
const activityListeners=new Set<()=>void>();
function activityChanged(){activityListeners.forEach(listener=>listener());}
function beginActivity(){activeOperations++;activityChanged();}
function endActivity(){activeOperations=Math.max(0,activeOperations-1);activityChanged();}
function subscribeActivity(listener:()=>void){activityListeners.add(listener);return ()=>{activityListeners.delete(listener);};}
function GlobalLoading(){const count=useSyncExternalStore(subscribeActivity,()=>activeOperations);return count>0?<div className="global-loading" role="status" aria-live="polite"><div className="global-loading-card"><span className="global-spinner" aria-hidden="true"/><span>Loading... (లోడ్ అవుతోంది...)</span></div></div>:null;}
async function fetch(input: RequestInfo | URL, init: RequestInit = {}) {
  const headers = new Headers(init.headers);
  if (accessToken && String(input).startsWith(api) && !headers.has('Authorization')) headers.set('Authorization', `Bearer ${accessToken}`);
  const method=(init.method||'GET').toUpperCase();
  const showGlobalLoader=method!=='GET'&&method!=='HEAD';
  if(showGlobalLoader)beginActivity();
  try { return await nativeFetch(input, { ...init, headers }); } finally { if(showGlobalLoader)endActivity(); }
}
