function bilingual(raw:string):string {
 const text=raw.replace(/^(?:Error|TypeError):\s*/, '');
 if (translations[text]) return `${text} (${translations[text]})`;
 let m=text.match(/^Cannot update (.+): (\d+) sold boxes need another active stock batch, but only (\d+) boxes are available\. Add at least (\d+) boxes before trying again\.$/);
 if(m)return `${text} (${m[1]} కోసం అమ్మిన ${m[2]} బాక్సులకు మరో స్టాక్ బ్యాచ్ అవసరం. అందులో ${m[3]} బాక్సులు మాత్రమే ఉన్నాయి. మళ్లీ ప్రయత్నించే ముందు కనీసం ${m[4]} బాక్సులు జోడించండి.)`;
 m=text.match(/^Cannot update (.+): (\d+) sold boxes could not be reassigned without changing their recorded costs\.$/);
 if(m)return `${text} (${m[1]} కోసం అమ్మిన ${m[2]} బాక్సులను నమోదైన ధరలు మార్చకుండా మరో స్టాక్‌కు మార్చలేము.)`;
 m=text.match(/^(.+) removed from active lists$/);if(m)return `${text} (${m[1]} యాక్టివ్ జాబితా నుండి తొలగించబడింది)`;
 m=text.match(/^Could not export bill: (.+)$/);if(m)return `${text} (బిల్‌ను ఎగుమతి చేయలేకపోయాము: ${m[1]})`;
 if(/\([\u0c00-\u0c7f]/u.test(text))return text;
 return `${text} (సమస్య ఏర్పడింది. వివరాలను తనిఖీ చేసి మళ్లీ ప్రయత్నించండి.)`;
}
function notify(message:string){if(message)window.alert(bilingual(message));}
function LoginGate() {
  const [signedIn,setSignedIn]=useState(!__API_BASE_URL__);
  const [checking,setChecking]=useState(!!__API_BASE_URL__ && !!getSaved(sessionKey));
  const [password,setPassword]=useState('');
  const [error,setErrorState]=useState('');
  const [busy,setBusy]=useState(false);
  const setError=(message:string)=>{setErrorState(message);if(message)notify(message)};
  useEffect(()=>{
    const token=getSaved(sessionKey);if(!__API_BASE_URL__||!token)return;
    let active=true;accessToken=token;
    fetch(api+'health').then(r=>{if(!active)return;if(r.ok){setSignedIn(true);return;}if(r.status===401){accessToken='';setSaved(sessionKey,'');}setErrorState(r.status===401?'Session expired. Please sign in again.':'Cannot reach the service. Please try again.');}).catch(()=>{if(active)setErrorState('Cannot reach the service. Please try again.')}).finally(()=>{if(active)setChecking(false)});
    return()=>{active=false};
  },[]);
  if(checking)return <main><section>Checking session... (సెషన్‌ను తనిఖీ చేస్తున్నాము...)</section></main>;
  if(signedIn)return <><div style={{textAlign:'right',padding:'1rem'}}>{__API_BASE_URL__&&<button onClick={()=>{accessToken='';setSaved(sessionKey,'');setPassword('');setSignedIn(false)}}>Sign out</button>}</div><App/></>;
  return <main><section><h1>Giri Fruits</h1><h2>Sign in</h2><form onSubmit={async e=>{e.preventDefault();if(busy)return;setBusy(true);setError('');try{const credential=btoa(unescape(encodeURIComponent(password)));const r=await fetch(api+'auth/session',{method:'POST',headers:{Authorization:`Bearer ${credential}`}});if(!r.ok){setError(r.status===429?'Too many attempts. Please wait 15 minutes.':'Incorrect password or service unavailable.');return;}const data=await r.json();if(typeof data.token!=='string'||!data.token.startsWith('session.'))throw Error('Invalid session response');accessToken=data.token;setSaved(sessionKey,data.token);setPassword('');setSignedIn(true)}catch{setError('Cannot reach the service. Please try again.')}finally{setBusy(false)}}}><label>Password<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required /></label><button disabled={busy}>{busy?'Signing in…':'Sign in'}</button>{error&&<p role="alert">{bilingual(error)}</p>}</form></section></main>;
}
